window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c40299af8776ce2f"]={"versions": [{"id": "FIG-c40299af8776ce2f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur AUTOSAR-ECUC-Parametrisierung (ECU Configuration Parameter Definition) im Modul Diagnostic Event Manager (<code>Dem</code>) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodellstruktur des Containers <code>DemEventParameter</code> (Teil 1) und dessen Relationen zu Konfigurationsparametern, Subcontainern sowie Referenzen auf globale Betriebs- und Freigabebedingungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DemEventParameter: EcucParamConfContainerDef</code> (Multiplizität 1..65535).</p>\n<p class=\"fig-p\">Enthaltene Parameter (+parameter):</p>\n<ul class=\"fig-list\">\n<li><code>DemEventId: EcucIntegerParamDef</code> (min = 1, max = 65535, symbolicNameValue = true).</li>\n<li><code>DemEventKind: EcucEnumerationParamDef</code> (Multiplizität 1..1) mit den Literalen <code>DEM_EVENT_KIND_SWC</code> und <code>DEM_EVENT_KIND_BSW</code>.</li>\n<li><code>DemEventAvailable: EcucBooleanParamDef</code> (Multiplizität 1..1).</li>\n<li><code>DemEventConfirmationThreshold: EcucIntegerParamDef</code> (min = 1, max = 255, defaultValue = 1, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Enthaltene Subcontainer (+subContainer):</p>\n<ul class=\"fig-list\">\n<li><code>DemCallbackInitMForE: EcucParamConfContainerDef</code> (Multiplizität 0..1), aggregiert <code>DemCallbackInitMForEFnc: EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n<li><code>DemCallbackEventUdsStatusChanged: EcucParamConfContainerDef</code> (Multiplizität 0..*), aggregiert <code>DemCallbackEventUdsStatusChangedFnc: EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n<li><code>DemCallbackClearEventAllowed: EcucParamConfContainerDef</code> (Multiplizität 0..1), aggregiert <code>DemCallbackClearEventAllowedFnc: EcucFunctionNameDef</code> (Multiplizität 0..1) und <code>DemClearEventAllowedBehavior: EcucEnumerationParamDef</code> (Multiplizität 1..1, defaultValue = DEM_NO_STATUS_BYTE_CHANGE) mit den Literalen <code>DEM_NO_STATUS_BYTE_CHANGE</code> und <code>DEM_ONLY_THIS_CYCLE_AND_READINESS</code>.</li>\n</ul>\n<p class=\"fig-p\">Referenzen (+reference / +destination):</p>\n<ul class=\"fig-list\">\n<li><code>DemOperationCycleRef: EcucReferenceDef</code> referenziert das Ziel <code>DemOperationCycle: EcucParamConfContainerDef</code> (Multiplizität 1..256).</li>\n<li><code>DemEnableConditionGroupRef: EcucReferenceDef</code> (Multiplizität 0..1) referenziert das Ziel <code>DemEnableConditionGroup: EcucParamConfContainerDef</code> (Multiplizität 0..255).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ECUC-Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Laufzeitsequenzen dar. Es definiert die statischen Konfigurationsbeziehungen und Callback-Hooks, die zur Generierungszeit des Dem ausgewertet werden, um Ereignisquellen (SW-C oder BSW) zu parametrieren, UDS-Statusänderungen und Reinitialisierungen per Funktionspointer zu binden sowie Freigabebedingungen und Betriebszyklen zuzuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsschema für die Dem-Ereignisgenerierung:</p>\n<ul class=\"fig-list\">\n<li>Jedes Diagnoseereignis muss zwingend eine eindeutige <code>DemEventId</code> besitzen, einem Event-Typ (<code>DemEventKind</code>) zugeordnet sein, eine Verfügbarkeit definieren (<code>DemEventAvailable</code>) und auf genau einen Betriebszyklus verweisen (<code>DemOperationCycleRef</code>).</li>\n<li>Die Schwellwertkonfiguration für Event-Bestätigungen (<code>DemEventConfirmationThreshold</code>) ist auf Werte von 1 bis 255 beschränkt.</li>\n<li>Callbacks für Initialisierung, Statusänderungen und Event-Löschberechtigungen sind optional; bei <code>DemCallbackClearEventAllowed</code> steuert <code>DemClearEventAllowedBehavior</code> das Verhalten des UDS-Statusbytes beim Löschen.</li>\n</ul>"}, {"id": "FIG-e6b4409ba8844d3d", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur AUTOSAR-ECUC-Parametrisierung (ECU Configuration Parameter Definition) im Modul Diagnostic Event Manager (<code>Dem</code>) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodellstruktur des Containers <code>DemEventParameter</code> (Teil 1) und dessen Relationen zu Konfigurationsparametern, Subcontainern sowie Referenzen auf globale Betriebs- und Freigabebedingungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DemEventParameter: EcucParamConfContainerDef</code> (Multiplizität 1..65535).</p>\n<p class=\"fig-p\">Enthaltene Parameter (+parameter):</p>\n<ul class=\"fig-list\">\n<li><code>DemEventId: EcucIntegerParamDef</code> (min = 1, max = 65535, symbolicNameValue = true).</li>\n<li><code>DemEventKind: EcucEnumerationParamDef</code> (Multiplizität 1..1) mit den Literalen <code>DEM_EVENT_KIND_SWC</code> und <code>DEM_EVENT_KIND_BSW</code>.</li>\n<li><code>DemEventAvailable: EcucBooleanParamDef</code> (Multiplizität 1..1).</li>\n<li><code>DemEventConfirmationThreshold: EcucIntegerParamDef</code> (min = 1, max = 255, defaultValue = 1, Multiplizität 1..1).</li>\n</ul>\n<p class=\"fig-p\">Enthaltene Subcontainer (+subContainer):</p>\n<ul class=\"fig-list\">\n<li><code>DemCallbackInitMForE: EcucParamConfContainerDef</code> (Multiplizität 0..1), aggregiert <code>DemCallbackInitMForEFnc: EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n<li><code>DemCallbackEventUdsStatusChanged: EcucParamConfContainerDef</code> (Multiplizität 0..*), aggregiert <code>DemCallbackEventUdsStatusChangedFnc: EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n<li><code>DemCallbackClearEventAllowed: EcucParamConfContainerDef</code> (Multiplizität 0..1), aggregiert <code>DemCallbackClearEventAllowedFnc: EcucFunctionNameDef</code> (Multiplizität 0..1) und <code>DemClearEventAllowedBehavior: EcucEnumerationParamDef</code> (Multiplizität 1..1, defaultValue = DEM_NO_STATUS_BYTE_CHANGE) mit den Literalen <code>DEM_NO_STATUS_BYTE_CHANGE</code> und <code>DEM_ONLY_THIS_CYCLE_AND_READINESS</code>.</li>\n</ul>\n<p class=\"fig-p\">Referenzen (+reference / +destination):</p>\n<ul class=\"fig-list\">\n<li><code>DemOperationCycleRef: EcucReferenceDef</code> referenziert das Ziel <code>DemOperationCycle: EcucParamConfContainerDef</code> (Multiplizität 1..256).</li>\n<li><code>DemEnableConditionGroupRef: EcucReferenceDef</code> (Multiplizität 0..1) referenziert das Ziel <code>DemEnableConditionGroup: EcucParamConfContainerDef</code> (Multiplizität 0..255).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ECUC-Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Laufzeitsequenzen dar. Es definiert die statischen Konfigurationsbeziehungen und Callback-Hooks, die zur Generierungszeit des Dem ausgewertet werden, um Ereignisquellen (SW-C oder BSW) zu parametrieren, UDS-Statusänderungen und Reinitialisierungen per Funktionspointer zu binden sowie Freigabebedingungen und Betriebszyklen zuzuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsschema für die Dem-Ereignisgenerierung:</p>\n<ul class=\"fig-list\">\n<li>Jedes Diagnoseereignis muss zwingend eine eindeutige <code>DemEventId</code> besitzen, einem Event-Typ (<code>DemEventKind</code>) zugeordnet sein, eine Verfügbarkeit definieren (<code>DemEventAvailable</code>) und auf genau einen Betriebszyklus verweisen (<code>DemOperationCycleRef</code>).</li>\n<li>Die Schwellwertkonfiguration für Event-Bestätigungen (<code>DemEventConfirmationThreshold</code>) ist auf Werte von 1 bis 255 beschränkt.</li>\n<li>Callbacks für Initialisierung, Statusänderungen und Event-Löschberechtigungen sind optional; bei <code>DemCallbackClearEventAllowed</code> steuert <code>DemClearEventAllowedBehavior</code> das Verhalten des UDS-Statusbytes beim Löschen.</li>\n</ul>"}, {"id": "FIG-7700f2b540b8d50d", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur AUTOSAR-ECUC-Parametrisierung (ECU Configuration Parameter Definition) im Modul Diagnostic Event Manager (<code>Dem</code>) der AUTOSAR Classic Platform. Das Diagramm spezifiziert die Metamodellstruktur des Containers <code>DemEventParameter</code> (Teil 1) und dessen Relationen zu Konfigurationsparametern, Subcontainern sowie Referenzen auf globale Betriebs- und Freigabebedingungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist der Container <code>DemEventParameter: EcucParamConfContainerDef</code> (Multiplizität 1..65535).</p>\n<p class=\"fig-p\">Enthaltene Parameter (+parameter):</p>\n<ul class=\"fig-list\">\n<li><code>DemEventId: EcucIntegerParamDef</code> (min = 1, max = 65535, symbolicNameValue = true).</li>\n<li><code>DemEventKind: EcucEnumerationParamDef</code> (Multiplizität 1..1) mit den Literalen <code>DEM_EVENT_KIND_SWC</code> und <code>DEM_EVENT_KIND_BSW</code>.</li>\n<li><code>DemEventAvailable: EcucBooleanParamDef</code> (Multiplizität 1..1).</li>\n<li><code>DemEventConfirmationThreshold: EcucIntegerParamDef</code> (min = 1, max = 255, defaultValue = 1, Multiplizität 1..1).</li>\n<li><code>DemEventAvailableInVariant: EcucBooleanParamDef</code> (defaultValue = true, Multiplizität 0..1).</li>\n<li><code>DemEventAssociatedIdentification: EcucIntegerParamDef</code> (min = 0, max = 65535, Multiplizität 0..1).</li>\n</ul>\n<p class=\"fig-p\">Enthaltene Subcontainer (+subContainer):</p>\n<ul class=\"fig-list\">\n<li><code>DemCallbackInitMForE: EcucParamConfContainerDef</code> (Multiplizität 0..1), aggregiert <code>DemCallbackInitMForEFnc: EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n<li><code>DemCallbackEventUdsStatusChanged: EcucParamConfContainerDef</code> (Multiplizität 0..*), aggregiert <code>DemCallbackEventUdsStatusChangedFnc: EcucFunctionNameDef</code> (Multiplizität 0..1).</li>\n<li><code>DemCallbackClearEventAllowed: EcucParamConfContainerDef</code> (Multiplizität 0..1), aggregiert <code>DemCallbackClearEventAllowedFnc: EcucFunctionNameDef</code> (Multiplizität 0..1) und <code>DemClearEventAllowedBehavior: EcucEnumerationParamDef</code> (Multiplizität 1..1, defaultValue = DEM_NO_STATUS_BYTE_CHANGE) mit den Literalen <code>DEM_NO_STATUS_BYTE_CHANGE</code> und <code>DEM_ONLY_THIS_CYCLE_AND_READINESS</code>.</li>\n</ul>\n<p class=\"fig-p\">Referenzen (+reference / +destination):</p>\n<ul class=\"fig-list\">\n<li><code>DemOperationCycleRef: EcucReferenceDef</code> referenziert das Ziel <code>DemOperationCycle: EcucParamConfContainerDef</code> (Multiplizität 1..256).</li>\n<li><code>DemEnableConditionGroupRef: EcucReferenceDef</code> (Multiplizität 0..1) referenziert das Ziel <code>DemEnableConditionGroup: EcucParamConfContainerDef</code> (Multiplizität 0..255).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches ECUC-Metamodell-Klassendiagramm stellt die Abbildung keine dynamischen Laufzeitsequenzen dar. Es definiert die statischen Konfigurationsbeziehungen und Callback-Hooks, die zur Generierungszeit des Dem ausgewertet werden, um Ereignisquellen (SW-C oder BSW) zu parametrieren, UDS-Statusänderungen und Reinitialisierungen per Funktionspointer zu binden sowie Freigabebedingungen und Betriebszyklen zuzuordnen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfigurationsschema für die Dem-Ereignisgenerierung:</p>\n<ul class=\"fig-list\">\n<li>Jedes Diagnoseereignis muss zwingend eine eindeutige <code>DemEventId</code> besitzen, einem Event-Typ (<code>DemEventKind</code>) zugeordnet sein, eine Verfügbarkeit definieren (<code>DemEventAvailable</code>) und auf genau einen Betriebszyklus verweisen (<code>DemOperationCycleRef</code>).</li>\n<li>Die Schwellwertkonfiguration für Event-Bestätigungen (<code>DemEventConfirmationThreshold</code>) ist auf Werte von 1 bis 255 beschränkt.</li>\n<li>Post-Build- bzw. variantenabhängige Ereignisverfügbarkeit kann über den optionalen Parameter <code>DemEventAvailableInVariant</code> konfiguriert werden (Standardwert: true).</li>\n<li>Eine zusätzliche Identifikationsnummer kann optional über <code>DemEventAssociatedIdentification</code> (0..65535) zugewiesen werden.</li>\n<li>Callbacks für Initialisierung, Statusänderungen und Event-Löschberechtigungen sind optional; bei <code>DemCallbackClearEventAllowed</code> steuert <code>DemClearEventAllowedBehavior</code> das Verhalten des UDS-Statusbytes beim Löschen.</li>\n</ul>"}], "trans": [{"from": "FIG-c40299af8776ce2f", "to": "FIG-e6b4409ba8844d3d", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Redaktionelle Typografiebereinigung: In den Klassenkopf-Beschriftungen wurde das Leerzeichen vor dem Doppelpunkt entfernt (z. B. <code>DemEventParameter : EcucParamConfContainerDef</code> zu <code>DemEventParameter: EcucParamConfContainerDef</code>, <code>DemEventId :EcucIntegerParamDef</code> zu <code>DemEventId: EcucIntegerParamDef</code> sowie bei den Literalen).</li>\n</ul>"}, {"from": "FIG-e6b4409ba8844d3d", "to": "FIG-7700f2b540b8d50d", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>DemEventParameter: Neuer boolescher Konfigurationsparameter <code>DemEventAvailableInVariant</code> vom Typ <code>EcucBooleanParamDef</code> mit <code>defaultValue = true</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>DemEventParameter: Neuer Integer-Konfigurationsparameter <code>DemEventAssociatedIdentification</code> vom Typ <code>EcucIntegerParamDef</code> mit <code>min = 0</code>, <code>max = 65535</code>, <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n</ul>"}]};
